(function (all) { var mine = all["nl"] = all["nl"] || {}; var add = {"manual.831d0f72d242":"Aan de slag","manual.f2f53974b760":"Freally Capture is een desktopstudio voor Windows, macOS en Linux. Deze handleiding beschrijft versie 1.2.1, de huidige versie.","manual.4b5f10daa08b":"Open Freally Capture. De eerste keer vraagt de app je de licentieovereenkomst te accepteren; daarna controleert een installatiewizard je videokaart en processor en stelt een encoder, een canvasformaat en een bitrate voor, telkens met de reden erbij.","manual.fe88634050bf":"De studio opent met het programmavoorbeeld en de docks <strong>Scènes</strong>, <strong>Bronnen</strong>, <strong>Mixer</strong> en <strong>Bediening</strong>. Er is geen account en je hoeft nergens in te loggen.","manual.4c937d2528ca":"Sta op <strong>macOS</strong> <strong>Schermopname</strong> toe — en ook <strong>Camera</strong> en <strong>Microfoon</strong> als je die gebruikt — in Systeeminstellingen → Privacy en beveiliging, en open de app daarna opnieuw. Op <strong>Linux met Wayland</strong> vraagt het eigen dialoogvenster van de desktop welk scherm of venster je wilt delen.","manual.adc8f305f8f8":"Voeg je eerste bron toe (zie <a href=\"#build-a-scene\">Een scène bouwen</a>) en je bent klaar om op te nemen of live te gaan.","manual.46e49bd74b1d":"Een scène bouwen","manual.f779d891c1f2":"Een scène is een stapel bronnen die op de videokaart wordt samengesteld. Een bron kan door meerdere scènes worden gedeeld.","manual.5a1c5f778fdb":"Klik in het dock <strong>Bronnen</strong> op <strong>Bron toevoegen</strong> en kies een type: <strong>Beeldscherm</strong>, <strong>Venster</strong>, <strong>Spel</strong>, <strong>Webcam / capture-kaart</strong>, <strong>Browser</strong>, <strong>Media</strong>, <strong>Afbeelding</strong>, <strong>Tekst</strong>, <strong>Kleur</strong> of <strong>Audio</strong>.","manual.2a2d9e2015b5":"Voeg een <strong>Beeldschermopname</strong> toe: het programmavoorbeeld vult zich met je scherm.","manual.80c8e9c8176f":"Voeg een <strong>Webcam</strong>-bron toe, sleep die naar een hoek van het canvas en wijzig het formaat met de grepen.","manual.264150f36676":"Leg er een overlay met een <strong>Afbeelding</strong> of <strong>Browser</strong> bovenop. De volgorde van de lijst is de volgorde op het canvas: bovenaan de lijst is vooraan.","manual.a329c46899d6":"Maak meer scènes in het dock <strong>Scènes</strong> — bijvoorbeeld „Begint zo”, „Gameplay” en „Zo terug” — en wissel daartussen.","manual.9c8d5730d1bb":"<strong>Tip:</strong> Wijzig de eigenschappen van een gedeelde bron één keer, en de wijziging geldt in elke scène die de bron gebruikt.","manual.fd869e76d280":"<strong>Het voorbeeld:</strong> op Windows, macOS en Linux met X11 wordt het programmavoorbeeld rechtstreeks vanaf de videokaart getekend, dus slepen, schalen en draaien voelen direct aan. Op Wayland wordt een standaardvoorbeeld gebruikt, met dezelfde bewerking op het canvas.","manual.87eca68fecaa":"Filters en overgangen","manual.36a962cf3902":"Stapel filters op elke bron, op de videokaart, en kies hoe de ene scène plaatsmaakt voor de volgende.","manual.4708b4dbab34":"Een chroma key toevoegen","manual.9df34cebcaf5":"Klik met rechts op een bron — bijvoorbeeld een camera voor een greenscreen — en kies <strong>Filters</strong>.","manual.9981601a6174":"Voeg <strong>Chroma Key</strong> toe en stel <strong>Sleutelkleur</strong>, <strong>Gelijkenis</strong>, <strong>Gladheid</strong> en <strong>Spill</strong> in: de gekozen kleur verdwijnt live op het canvas.","manual.b76bd309a9f6":"Voeg naar behoefte meer filters toe — <strong>Kleurcorrectie</strong>, <strong>LUT</strong>, <strong>Vervagen</strong>, <strong>Masker</strong>, <strong>Verscherpen</strong> — en sleep ze om de volgorde in de keten te wijzigen.","manual.db41fe5a40e4":"Een overgang instellen","manual.bea9e11be98d":"Open in <strong>Bediening</strong> de overgangskiezer, kies <strong>Snijden</strong>, <strong>Vervagen</strong>, <strong>Schuiven</strong>, <strong>Vegen</strong>, <strong>Stinger</strong> of <strong>Luma-wipe</strong>, en stel een duur in.","manual.eada58ce5b2e":"Kies bij een <strong>Stinger</strong> de media en het overgangspunt; kies bij een <strong>Luma-wipe</strong> het verloop en de zachtheid.","manual.79756cb8b209":"Wissel van scène om de overgang te zien. In Studiomodus speelt ze af als je het voorbeeld naar het programma stuurt.","manual.2c0c025b4264":"Compositor en visuele effecten","manual.b768e85eff32":"3D-kanteling, downstream keyers, bevriezen en klonen, een familie vervagingen, bewegingsovergangen met regels, een shaderstudio, Bézier-maskers en track-matte-stingers.","manual.d2b720eca5a5":"3D-kanteling en perspectief","manual.d665cc2f2296":"Open <strong>Transformatie bewerken…</strong> voor een item en stel <strong>Kantelen X</strong>, <strong>Kantelen Y</strong> en een sterkte voor <strong>Perspectief</strong> in om de bron in 3D te plaatsen. Een transformatie zonder kanteling wordt precies zo weergegeven als voorheen.","manual.c4077ba2b72d":"Downstream-keyers","manual.d4220af54ed9":"Open <strong>Extra → Downstream-keyers</strong> en voeg een willekeurige bron toe als laag over de <strong>programma-uitvoer</strong>, boven elke scène en door elke scènewissel heen — een zenderlogo, een LIVE-badge, een lower third.","manual.0677e571c1f8":"Wijzig de volgorde van de lagen en stel per laag de dekking, positie, grootte en aan of uit in. Ze verschijnen net zo goed in het voorbeeld, de opname, de stream en de multiview.","manual.1e484119e149":"Stilstaand beeld en bronnen klonen","manual.4cdb8e22f58b":"Klik met rechts op een bron, open <strong>Filters</strong> en voeg <strong>Bevriezen</strong> toe: het filter houdt het laatste frame vast in programma, voorbeeld, opname en stream tegelijk. Zet het uit om weer verder te gaan.","manual.59fd957b48dc":"Klik op de knop <strong>Klonen</strong> (⧉) in de regel van een bron om één bron in meerdere scènes of op meerdere plekken te zetten, elke kloon met een eigen transformatie en eigen filters.","manual.a90410d6b30c":"Vervagingen","manual.eeb69e428aa3":"Voeg in de <strong>Filters</strong> van een bron een van de vervagingen naast de Gaussische toe: <strong>Richting</strong> (een bewegingsstreep onder een hoek), <strong>Radiaal</strong> (een draaiing rond een middelpunt), <strong>Zoom</strong> (een dolly-zoomstreep) of <strong>Pixeleren</strong> (een mozaïek).","manual.54261c9f6b8f":"De bewegingsovergang en overgangsregels","manual.ef17a04962be":"Kies de overgang <strong>Beweging</strong>: items die in beide scènes staan, glijden van hun oude positie, schaal, rotatie en bijsnijding naar de nieuwe in plaats van te snijden, en items die maar in één scène staan, faden in of uit.","manual.e31792f9e737":"Open <strong>Extra → Overgangsregels</strong> om één paar scènes een eigen overgang en duur te geven. Voor de eigen opkomst van een item stel je onder <strong>Transformatie bewerken…</strong> een infade bij <strong>Onthullen</strong> in.","manual.bb4e30a1ea68":"De WGSL-shaderstudio","manual.e475acf03bea":"Voeg een <strong>eigen WGSL-effect</strong> als filter toe en bewerk het live. De schuifregelaars worden gemaakt uit <code>// @param</code>-annotaties, en een ingebouwde galerij bevat grijswaarden, inverteren, scanlijnen en vignet.","manual.424ca3316822":"<strong>Tip:</strong> Een shader wordt gecompileerd en gecontroleerd terwijl je typt. Een ongeldige shader wordt genegeerd en de bron wordt zonder filter weergegeven — nooit een crash.","manual.c24e8b5ee2c0":"Bézier-maskers","manual.37870edaacbc":"Voeg het filter <strong>vrij getekend masker</strong> toe en teken een gesloten pad: sleep de grepen, dubbelklik om een punt toe te voegen, klik met rechts om er een te verwijderen. Het heeft vooraf ingestelde vormen, verzachting per rand en inverteren.","manual.f44ad1306530":"Exporteer een pad als grijswaardenpatroon voor een <strong>luma-wipe</strong> om de vorm als overgang te hergebruiken.","manual.e4c8b0c52b3e":"Track-matte-stingers","manual.b35494db6ce6":"Laat een stinger zijn transparantie meedragen als <strong>Track matte</strong>, met de vulling en de matte <strong>Naast elkaar</strong> of <strong>Gestapeld</strong>, zodat de transparantie codecs overleeft die haar weggooien (H.264 en HEVC). Laat optioneel <strong>het programmageluid ducken</strong> onder het eigen geluid van de stinger zolang die speelt.","manual.3879f0c73d18":"Overlays en meer bronnen","manual.cea21c089e39":"Replay, afspeellijsten, titels, meters, een statistieken-overlay, timers, een invoer-overlay en twee netwerkbronnen, allemaal via het menu <strong>+ / Bron toevoegen</strong> van het dock <strong>Bronnen</strong>.","manual.4a459b922e4b":"Directe herhaling","manual.2e042aa67065":"Activeer eerst de replaybuffer (<strong>Replay activeren</strong> in het dock <strong>Bediening</strong>), kies daarna <strong>Instant replay</strong> via <strong>+ / Bron toevoegen</strong> en zet de bron in een scène.","manual.d7645da473a6":"Speel de laatste seconden in het programma af met je sneltoets voor replay — gekopieerd zonder nieuwe codering en afgespeeld op <strong>100%</strong>, <strong>50%</strong> of <strong>25%</strong> snelheid, vertraagd in plaats van met verzonnen frames. Spoel of pauzeer terwijl hij speelt.","manual.5b8095e70de0":"Aan het eind maakt de bron zichzelf leeg, zodat de show vanzelf terugkeert naar live.","manual.6433eaab9b10":"<strong>Tip:</strong> Een replay in slow motion is bewust zonder geluid: vertraagd geluid zou uitsmeren, dus het wordt weggelaten in plaats van nagebootst.","manual.f0b63d46cd74":"Media-afspeellijst en achtergrondmuziek","manual.37ed12f9d130":"Voeg <strong>Media-playlist (naadloos)</strong> toe en maak een geordende lijst met in- en uitpunten en cuepunten per item. De hele lijst speelt af via één decoder, dus de overgangen zijn framenauwkeurig en echt naadloos.","manual.ef41fa6ad9b5":"Kies hoe de lijst afspeelt — <strong>Herhalen</strong>, <strong>Willekeurig</strong> of <strong>Laatste vasthouden</strong> — en loop er met de sneltoetsen voor volgende en vorige doorheen. Een afspeellijst met alleen audio toont de <strong>naam van het huidige nummer</strong> op het canvas en speelt af via een eigen mixerkanaal; klik op de knop <strong>Monitor</strong> van dat kanaal om hem te horen.","manual.6e641ae2bd92":"Kies voor muziek die speelt zonder dat er iets in beeld staat in plaats daarvan <strong>+ / Bron toevoegen → Achtergrondmuziek…</strong> en kies een of meer <code>.mp3</code>-, <code>.wav</code>- of <code>.flac</code>-bestanden, desgewenst in willekeurige volgorde. Het dempt het eigen geluid van een video-achtergrond, zodat er altijd maar één ding te horen is.","manual.b9aad55133bf":"De ontwerper voor titels en scoreborden","manual.5382c093aaef":"Voeg <strong>Titel / scorebord</strong> toe om de ontwerper te openen: stapel lagen met <strong>Tekst</strong>, <strong>Afbeelding</strong> en <strong>Vorm</strong>, met tekst met omlijning en schaduw en animaties voor in en uit (vervagen, schuiven, wipe).","manual.7b8fea70655a":"Koppel velden aan een gevolgd bestand (een CSV-cel of een JSON-pointer) of aan een studiovariabele, en bedien het daarna live: wijzig een naam, bewerk de stand of speel de animatie af zonder de scène aan te raken.","manual.88a9422e37a9":"De audiovisualizer","manual.87f4a5bdd624":"Voeg <strong>Audiovisualizer</strong> toe en kies een stijl — <strong>Spectrumbalken</strong>, een <strong>Oscilloscoop</strong> of stereo-<strong>VU-meters</strong> — en koppel die aan een mixerkanaal, een spoor of de mastermix. Ook het geluid van een video-achtergrond wordt weergegeven.","manual.0ae90a461adb":"Zet in de <strong>Eigenschappen</strong> van de bron <strong>Klassieke kleuren</strong> aan voor groene, gele en rode banden, of laat het uit voor één effen kleur. Grootte, aantal balken en valsnelheid vind je daar ook.","manual.0d1ceffb08ba":"<strong>Tip:</strong> De visualizer luistert <strong>na de fader</strong>, dus een gedempte bron wordt plat weergegeven: hij toont precies wat je hoort.","manual.ec642e1cf0cc":"De statistieken-overlay, splittimer en invoer-overlay","manual.6b4fe6f81cb0":"Voeg <strong>Prestatiestatistieken (HUD)</strong> toe om de gemeten cijfers van het statistiekendock op het canvas te tonen — frames per seconde, CPU, geheugen, GPU-compositietijd, verloren frames en live bitrate — elke regel aan of uit. GPU-gebruik is bewust weggelaten, omdat het niet wordt gemeten.","manual.cbd8a4b88736":"Voeg <strong>Speedrun-splittimer</strong> toe, importeer een LiveSplit-bestand <code>.lss</code> en draai het met globale sneltoetsen voor splitsen, ongedaan maken, overslaan en resetten, tegen je persoonlijk record, beste segmenten of gemiddelde. Het bestand wordt alleen gelezen; een run wordt nooit teruggeschreven.","manual.fbf4bbeaf903":"Voeg <strong>Invoer-overlay (toetsen/pad)</strong> toe om toetsenbord, muis en gamepad live te tonen, in een van vier indelingen (WASD, een compact toetsenbord, een pad met twee sticks, een 8-weg fightstick). Toetsenbord en muis werken op Windows; gamepads werken op alle drie de systemen.","manual.bf794edb3c25":"De balk met sociale kanalen","manual.5f898056ef11":"Voeg <strong>Sociale balk</strong> toe via <strong>+ / Bron toevoegen</strong>: een paneel met je accountnamen. Kies per regel een platform — <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> als gekleurde badges, of <strong>Aangepast</strong> met je eigen label en kleur — en typ de accountnaam (bijvoorbeeld <code>@mychannel</code>). Voeg een optionele kopregel toe („Volg mij”), wijzig de volgorde van de regels en stel de tekstgrootte en kleuren in.","manual.1dab9389547a":"Elk veld blijft te bewerken in de <strong>Eigenschappen</strong> van de bron. Regels zonder accountnaam worden overgeslagen, dus je kunt een volledige lijst bewaren en alleen invullen wat je gebruikt.","manual.1a4ac3c2e0bf":"Het uitgelichte chatbericht","manual.c5d58a7d58be":"Open <strong>Extra → Uitgelicht chatbericht…</strong> (of het opdrachtenpalet). Het toont de nieuwste regels uit elke actieve chat-overlay: klik bij een regel op <strong>Uitlichten</strong> om die als banner in het programma te zetten, zichtbaar voor kijkers van de stream en de opname.","manual.162d364796a2":"Stel in het dialoogvenster de kleuren voor <strong>banner</strong> en <strong>tekst</strong> in, en klik op <strong>Weghalen</strong> om hem uit de uitzending te halen. Het vastzetten zelf verdwijnt bewust bij een herstart: de shout-out van gisteren blijft niet rondspoken in de show van vandaag.","manual.89a84c53e014":"Cursormarkering en klikeffecten","manual.d0a5d9fb047d":"Klik met rechts op een beeldscherm- of vensteropname, open <strong>Filters</strong> en voeg <strong>Cursoreffecten</strong> toe: een <strong>Cursorhalo</strong> (kleur en straal), <strong>Klikgolven</strong> met een kleur voor links en rechts, en optionele <strong>Toetsweergave</strong> naast de aanwijzer. Wijzigingen zijn live te zien.","manual.4a17c44757e4":"<strong>Opmerking:</strong> Cursoreffecten werken alleen op Windows; macOS en Linux tekenen de cursor zelf. De invoer-overlay en de toetsweergave lezen invoer <strong>alleen zolang ze aan staan</strong>, en tekenen die rechtstreeks in het beeld: er wordt niets bewaard of gelogd.","manual.8bdb1aadf964":"Netwerkbronnen: LAN-ontvangst en Freally Link","manual.797fe86a1fe8":"Voeg <strong>LAN-ontvangst (SRT/RTMP-listener)</strong> toe om op deze computer een listener te openen, en richt daarna een camera-app op een telefoon, een encoder of een tweede computer op het getoonde adres (met een QR-code). Het beeld komt in de scène terecht met een eigen mixerkanaal. SRT kan een optionele AES-wachtwoordzin hebben; RTMP heeft zelf geen authenticatie, dus het formulier geeft de voorkeur aan SRT.","manual.e2761818ccef":"Om te delen tussen twee exemplaren van Freally Capture zet je op de <strong>verzendende</strong> computer de uitvoer <strong>Freally Link</strong> aan en stel je de <strong>koppelsleutel</strong> in — zonder sleutel kan de uitvoer niet aan. Voeg op de <strong>ontvangende</strong> computer <strong>Freally Link (andere instantie)</strong> toe, klik op <strong>LAN scannen</strong> en typ de sleutel: het programma van de zender verschijnt als bron. Geen van beide kanten heeft ffmpeg nodig, en een ontvanger zonder de sleutel ziet nooit een frame.","manual.a793cb271e32":"<strong>Opmerking:</strong> Beide netwerkbronnen staan <strong>uit totdat je ze toevoegt</strong>, blijven op je eigen netwerk en raken het internet nooit: niets vindt jou, en niets belt naar buiten.","manual.de10be5dcf2c":"De aftelling „Begint zo”","manual.71b47ef78ea4":"Een wachtscherm vóór de show in één klik: een grote aftelling naar het begin van de show over een afbeelding, een GIF, een video, een verloop of muziek, die op nul knippert en wacht tot jij naar de show schakelt.","manual.303493002776":"De aftelling toevoegen","manual.f78f2994b5d5":"Open in het dock <strong>Bronnen</strong> <strong>+ / Bron toevoegen</strong> en kies <strong>Begint zo…</strong>. Dit zet een aftelling over het hele canvas — een bijschrift boven een groot getal — in de scène.","manual.c4bff5a4f06e":"Typ het <strong>bijschrift</strong> („Begint zo”, „Zo terug”) en stel daarna de tijd in met de <strong>klokkiezer</strong>: een <strong>uur</strong> (1–12), een <strong>minuut</strong> in stappen van vijf minuten, en <strong>AM</strong> of <strong>PM</strong>. De bron telt af naar dat tijdstip van de dag.","manual.59b00df516f1":"Bij nul <strong>knippert de aftelling en blijft ze op 0:00:00 staan</strong> — ze wisselt nooit zelf van scène. Schakel naar je livescène zodra je klaar bent. Elk veld blijft te bewerken in de <strong>Eigenschappen</strong> van de bron.","manual.1dfb2d817d39":"Een achtergrond kiezen","manual.edc2450aeecd":"Kies de vulling: een <strong>Verloop</strong> van twee kleuren (de standaard), een <strong>Effen</strong> kleur, een <strong>Afbeelding</strong> (klik op <strong>Bladeren…</strong>), of <strong>Transparant</strong> om een bron eronder te laten doorschijnen.","manual.07a5fd9ac032":"Kies een <strong>GIF</strong>- of <strong>video</strong>bestand en het herhaalt achter de cijfers, <strong>passend geschaald en gecentreerd</strong>, zodat het hele beeld zichtbaar is en er niets wordt bijgesneden.","manual.1cda5be75376":"Voeg <strong>Achtergrondmuziek</strong> toe via <strong>Bladeren…</strong> in het dialoogvenster (MP3, WAV, FLAC, M4A, AAC, OGG of Opus). Ze herhaalt, je hoort haar in het voorbeeld, en ze maakt deel uit van de opname en de stream. Het eigen geluid van een video-achtergrond wordt gedempt, zodat er altijd maar één ding te horen is.","manual.b39b6b7add20":"<strong>Tip:</strong> Voor muziek achter een eenvoudig scherm laat je de achtergrond op Verloop of Transparant staan en voeg je de muziek toe: een strakke aftelling met een soundtrack.","manual.84f506f4fca5":"De audiomixer","manual.480e299c8728":"Mix elke audiobron, stuur die naar maximaal 6 sporen en maak je microfoon schoon — allemaal live.","manual.bcbc220b3e63":"Elke audiobron is een kanaal in de <strong>Mixer</strong>: de naam, een niveaumeter, een fader, dempen, monitor, filters en spoorstippen (1–6).","manual.03b920dc5376":"Sleep een fader om het niveau in te stellen, klik op <strong>Dempen</strong> of <strong>Monitor</strong>, en stuur de bron naar een van de 6 sporen.","manual.9a9991c7dc36":"Open de <strong>filters</strong> van een bron en voeg <strong>Ruisonderdrukking</strong> (klassieke signaalverwerking, geen AI), <strong>Noise Gate</strong>, <strong>Compressor</strong>, <strong>Limiter</strong>, <strong>EQ</strong> of <strong>Versterking</strong> toe.","manual.1a58b91bc5aa":"Koppel een sneltoets voor <strong>Push-to-talk</strong> of <strong>Push-to-mute</strong>, en houd de <strong>LUFS</strong>-meter in de gaten voor de luidheid van het programma.","manual.7158a36ed4d5":"<strong>Opmerking voor macOS:</strong> macOS geeft apps niet uit zichzelf „wat je hoort”. Gebruik ScreenCaptureKit-audio (macOS 13 of nieuwer) waar dat beschikbaar is, of installeer een virtueel apparaat zoals BlackHole en kies dat als bron voor systeemgeluid. Freally Capture begeleidt je daarbij en blijft opnemen, ook als één bron niet kan worden geopend.","manual.bfdd510698ef":"Opnemen","manual.e39b756fce99":"Neem het programma op meerdere sporen op met de hardware-encoder van je videokaart, of verliesvrij in het eigen formaat van Capture.","manual.ad438c2dbf4b":"Kies in <strong>Instellingen → Uitvoer</strong> een encoder. Freally Capture vindt <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> of <strong>VideoToolbox</strong> en kiest de beste; <strong>x264</strong> op de processor is er altijd als terugvaloptie.","manual.3bc1870f8449":"Kies een container — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> of <strong>WebM</strong> — of het eigen verliesvrije formaat <strong>freally-video</strong> van Capture (<code>.frec</code>), waarvoor verder niets geïnstalleerd hoeft te zijn.","manual.e2a332927058":"Stuur bronnen naar audiosporen (maximaal 6), zodat de microfoon, het systeemgeluid en je gasten gescheiden blijven voor de montage. Zet optioneel <strong>bestandssplitsing</strong> en <strong>een lokale kopie met aparte sporen tijdens het streamen</strong> aan.","manual.e0fa2f5a9430":"Klik in <strong>Bediening</strong> op <strong>Opname starten</strong>. Een groene <strong>REC</strong>-stip toont de tijd en het aantal sporen. Klik op <strong>Stoppen</strong> om het bestand af te ronden.","manual.b1eb969490f1":"<strong>Opmerking over codecs:</strong> MP4 met H.264 en AAC (en HEVC of AV1) gebruikt codecs waarop patenten rusten. Die komen van <strong>ffmpeg</strong>, dat <em>niet wordt meegeleverd</em>: Freally Capture downloadt het de eerste keer dat je het nodig hebt en controleert het. Voor het verliesvrije formaat <strong>freally-video</strong> hoeft niets te worden gedownload.","manual.691bff5377a8":"Opnemen en herhalen in de diepte","manual.3c2d08430816":"Alles rond het bestand: aparte opnames van elke bron, een clip-trimmer, echte transparantie, splitsen en markeringen bij gebeurtenissen, taken na de opname, een integriteitscontrole en SMPTE-tijdcode. Alles staat uit totdat je het aanzet, en niets ervan gaat online.","manual.537ffa2b9063":"ISO-opname per bron","manual.e57aa725fa41":"Open <strong>Instellingen → Uitvoer</strong> en zoek <strong>ISO-opname</strong>. Zet <strong>„{name}” als eigen ISO-bestand opnemen</strong> aan voor elke bron die je schoon wilt hebben: elke bron wordt vóór het samenstellen opgenomen, met de grootte en framerate van het canvas, zodat elk bestand op een montagetijdlijn precies gelijkloopt met het programma. Elke gast op afstand is een bron, dus ook elke gast krijgt een eigen bestand.","manual.4bce8f25ec9c":"Laat <strong>Opnemen met de filters van de bron</strong> aangevinkt voor het bewerkte beeld, of vink het uit voor de onbewerkte bron, en kies per opname het <strong>ISO-formaat</strong> en de <strong>ISO-video-encoder</strong>. Het geluid wordt na de filters maar vóór de fader en het dempen afgenomen, zodat een mixbeslissing een ISO-bestand nooit stil maakt.","manual.7f29ae4e2c55":"<strong>Tip:</strong> Twee ISO-opnames gaan prima op een videokaart uit het middensegment; elke extra opname kost nog een render en een encode, en het paneel zegt dat ook.","manual.b2aad668b8b9":"De trimmer voor replays en clips","manual.c8af16e1cd4f":"Open een opgeslagen opname vanuit de lijst met opnames in het venster <strong>Trimmen</strong>, loop er stap voor stap doorheen met <strong>Één frame terug</strong> en <strong>Één frame vooruit</strong>, en zet je punten met <strong>In-punt</strong> en <strong>Uit-punt</strong> terwijl je kijkt.","manual.1f80dfd03a36":"Kijk naar de badge voordat je exporteert. Een groene <em>„Exporteert zonder opnieuw te coderen”</em> betekent dat het in-punt op een keyframe ligt (vrijwel direct en verliesvrij); de amberkleurige badge waarschuwt dat er opnieuw wordt gecodeerd — druk op <strong>Keyframe</strong> om het in-punt naar een keyframe te laten springen voor een verliesvrije knip. Klik op <strong>Clip exporteren</strong>, of op <strong>9:16</strong> om een verticale versie te exporteren.","manual.8a92b0b480f4":"Opnemen met transparantie","manual.79bfd450e6aa":"Zet in <strong>Instellingen → Uitvoer</strong> de optie <strong>Opnemen met transparantie (alfa)</strong> aan om het programma over een transparante achtergrond op te nemen in het <code>.frec</code>-formaat van Capture. De opname krijgt een eigen transparante render, zodat je voorbeeld en je stream het normale beeld houden. Exporteer vanuit de lijst met opnames een <code>.mov</code> in <strong>ProRes 4444</strong> of <strong>QuickTime Animation (QTRLE)</strong> voor je montageprogramma; MP4 en MKV maken de transparantie plat.","manual.fade0a9d0454":"<strong>Opmerking:</strong> Transparantie is alleen een vlag in de header van <code>.frec</code>, dus deze bestanden spelen overal af waar <code>.frec</code> afspeelt, en oudere bestanden openen als ondoorzichtig.","manual.33e5c9a96c5d":"Splitsen en automatische markeringen","manual.5596d47693a3":"Kies in de splitsinstellingen voor <code>.frec</code> of er een nieuw bestand begint bij een <strong>scènewissel</strong>, een <strong>marker</strong> of een <strong>rundown-stap</strong>. Elk deel begint op het exacte frame van die gebeurtenis, en een deel duurt minstens één seconde, zodat een reeks snel opeenvolgende gebeurtenissen geen stapel piepkleine bestanden kan opleveren.","manual.7fc20a49c196":"Zet <strong>Automatisch hoofdstukmarkeringen plaatsen bij studiogebeurtenissen</strong> aan om scènewissels, opgeslagen replays, herverbindingen, reeksen verloren frames, alarmen en regelacties als hoofdstukken te markeren. Ze komen in de hoofdstuktitels van MKV en in het bestand <code>.chapters.txt</code> bij de opname, samen met de markeringen die je met je sneltoets plaatst.","manual.519fceb746f3":"Na de opname: de pipeline en de integriteitscontrole","manual.561bb55d7a18":"Stel per profiel een <strong>Pipeline na opname</strong> samen uit een vaste reeks stappen — <strong>Verifiëren</strong>, <strong>Hermuxen naar MP4</strong>, <strong>Luidheid normaliseren</strong>, <strong>Hernoemen</strong>, <strong>Verplaatsen naar map</strong>, <strong>Kopiëren naar map</strong>, <strong>Tonen in bestandsbeheer</strong> en <strong>Lua-scripts melden</strong>. Hij draait op de achtergrond met een live wachtrij en stopt bij de eerste fout. Er is bewust geen stap „willekeurige opdracht uitvoeren”.","manual.2f93cddd1f21":"Voer de integriteitscontrole uit na een opname of wanneer je maar wilt, voor een duidelijk OK, waarschuwing of fout op <strong>Container</strong>, <strong>Videocontinuïteit</strong>, <strong>Audiocontinuïteit</strong>, <strong>audio- en video-interleaving</strong> en <strong>Duur</strong>. <code>.frec</code>-bestanden krijgen de diepgaande controle; andere bestanden krijgen via ffmpeg een controle van structuur en decodering.","manual.0d291aee5546":"Een deelbare kopie exporteren als je stopt","manual.124d2a00ed27":"Vink in <strong>Instellingen → Uitvoer</strong>, met de container op <code>.frec</code>, <strong>Ook een deelbare MP4 naast de master opslaan</strong> aan. Als een opname klaar is, schrijft een export op de achtergrond naast de verliesvrije master een <code>.mp4</code> die iedereen kan afspelen.","manual.a37303723389":"De kopie verschijnt in de wachtrij na de opname, krijgt een naam die nooit iets overschrijft en raakt de master nooit aan. Dit staat uit totdat je het aanzet.","manual.7ed8656eb1ff":"SMPTE-LTC-tijdcode","manual.3d97874c3064":"Open <strong>SMPTE-timecode (LTC)</strong>, zet <strong>LTC op een track genereren</strong> aan en kies het mixerspoor en de framerate om externe recorders en camera's te voeden. Stel <strong>LTC lezen van</strong> in op een audio-ingang om een tijdcoderegel op de statistieken-overlay te tonen en LTC-hoofdstukmarkeringen te plaatsen. Klassieke audiotijdcode, volledig offline, nauwkeurig tot op één frame bij 24, 25 en 30 fps.","manual.a9f690169703":"Live gaan","manual.8f6df4580812":"Stream rechtstreeks vanaf je computer naar een platform via RTMP of RTMPS — nooit via een server van ons.","manual.dba22b61cdcc":"Open <strong>Instellingen → Stream</strong> en klik op <strong>Doel toevoegen</strong>. Kies <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> of <strong>Aangepaste RTMP</strong>.","manual.2192731aac47":"Plak je <strong>streamsleutel</strong> — die blijft op je computer en wordt gemaskeerd getoond — en stel de bitrate en de encoder voor die dienst in.","manual.040014e94f16":"Klik in <strong>Bediening</strong> op <strong>Ga live</strong>. Het <strong>Live</strong>-lampje gaat aan, en het statistiekendock toont je bitrate, de verloren frames en de toestand van de stream.","manual.0cd441959cb4":"Als je verbinding wegvalt, <strong>maakt Freally Capture zelf opnieuw verbinding</strong>, en je lokale opname loopt door, wat de stream ook doet. Stel een <strong>streamvertraging</strong> in als je die wilt.","manual.dc8ebcea4893":"Klik op <strong>Stream beëindigen</strong> om te stoppen.","manual.973adc03e43c":"Uitzendveiligheid","manual.53fa9293a65e":"De show niet kwijtraken — ervoor, tijdens en erna.","manual.de8792b14216":"Vooraf: de check vóór het live gaan","manual.ed9a4b7bfaf5":"Een klik op <strong>Ga live</strong> voert eerst een checklist uit: streambestemmingen hebben een sleutel, er is een bruikbare encoder gevonden, elke bron is gezond en er is genoeg schijfruimte voor de opname — elk groen of rood, met een oplossing in één klik — plus herinneringen over de niveaus van microfoon en bureaubladgeluid en over de replaybuffer, die een show met alleen een scherm nooit tegenhouden. Een instelling kan <strong>Ga live tegenhouden totdat elke blokkerende controle groen is</strong>; anders is er „Toch live gaan”.","manual.9b63c5c64ba1":"Tijdens: alarmen, status en failover","manual.9c386b745073":"<strong>Veiligheidsalarmen</strong> waken terwijl je live bent of opneemt: stil programmageluid, aanhoudende oversturing, een zwart of bevroren beeld, en een <em>voorspelling</em> van een vollopende schijf („nog ongeveer 22 minuten bij de huidige bitrate”). Ze verschijnen als een banner die je kunt sluiten, en schermlezers kondigen ze aan — nooit een dialoogvenster dat de show onderbreekt.","manual.b7c8c66a5330":"Het <strong>dashboard met de status van bronnen</strong> (opdrachtenpalet → „Status van bronnen…”) toont voor elke bron de toestand, de framerate, de leeftijd van het laatste frame, de verloren frames en de herstarts, met <strong>Herstarten</strong> en <strong>Eigenschappen</strong> bij elke bron.","manual.92bd60ef963b":"Als de hardware-encoder midden in een stream of opname uitvalt — een driverreset, een zwaarbelaste videokaart — schakelt <strong>encoder-failover</strong> over naar een andere hardware-encoder of naar x264. De stream maakt opnieuw verbinding en blijft in de lucht, de opname gaat verder in een nieuw bestand, en een melding zegt precies wat er is gebeurd. Netwerkproblemen leiden nooit tot een overschakeling.","manual.50a02fe4fe7b":"De <strong>paniekknop</strong> (een globale sneltoets die je zelf kiest) zet het programma — en het verticale canvas en eventuele projectoren — op een privacyscherm, stopt alle opnamebronnen en dempt al het geluid, de microfoon inbegrepen, terwijl de stream en de opname verbonden blijven. Terugkeren vraagt een bewuste bevestiging in twee stappen. Stel de kleur of afbeelding van dat scherm in naast de sneltoets in <strong>Instellingen → Sneltoetsen</strong>.","manual.a73a2857361e":"Erna: veilige opnames en netjes afsluiten","manual.bf07b060e7e7":"Opnames in MP4 en MOV worden in <strong>fragmenten</strong> geschreven, zodat een crash of een stroomstoring toch een afspeelbaar bestand achterlaat (bij MKV en <code>.frec</code> was dat al zo). Als een sessie midden in een opname eindigt, biedt de volgende start aan om met één klik te <strong>Herstellen</strong> naar een kopie <code>(repaired)</code>; het origineel wordt nooit aangeraakt.","manual.da5eeb31c1b8":"Afsluiten terwijl je live bent, opneemt of replay hebt geactiveerd, laat eerst zien wat er gaat gebeuren en sluit daarna <strong>in volgorde</strong> af: de stream beëindigen, de opname afronden, de replaybuffer opslaan, je werk opslaan.","manual.26b3f2c32e05":"<strong>Bestandsnamen van opnames</strong> volgen een sjabloon (<strong>Instellingen → Uitvoer</strong>) opgebouwd uit tokens — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — voor opnames, replays en stilstaande beelden, met eigen mappen voor replays en stilstaande beelden.","manual.27c3f23547ac":"<strong>Diagnostiek exporteren</strong> slaat een bundel technische gegevens op in een bestand op je computer, samengesteld volgens een strikte lijst van wat is toegestaan, zodat streamsleutels, wachtwoorden, bestandspaden en namen er nooit in staan. Je kunt eerst lezen wat erin zit; het blijft waar je het opslaat en wordt nooit ergens heen gestuurd.","manual.5199babf9b90":"Bronnen en apparaten","manual.306121fdda68":"Alles tussen de lens en het canvas: testsignalen, synchronisatiekalibratie, tekst uit een bestand, timers, de sneltoetsenkaart, de mixer in de diepte en echte apparaatbediening.","manual.5eacf1ee941f":"Testsignalen en kalibratie van A/V-synchronisatie","manual.920b7abd63cc":"Voeg een bron <strong>Testsignaal</strong> toe (<strong>Bronnen → + → Testsignaal</strong>): kleurenbalken, een kalibratieraster, een bewegingssweep, een lijntoon van 1 kHz op −20 dBFS, of een gecombineerde <strong>flits en piep</strong> voor de synchronisatie van beeld en geluid — beeld en geluid vanuit één klok. Controleer een projector, een encoder of een streambestemming zonder dat er een camera is aangesloten.","manual.788073298328":"Open de werkbank <strong>Kalibratie van A/V-synchronisatie</strong> (opdrachtenpalet → „Kalibratie van A/V-synchronisatie…”). Kies de camera en microfoon die je wilt gelijkzetten, richt de camera op het knipperende programma (het dialoogvenster kan daarvoor een projector op volledig scherm openen) en laat hem ongeveer twaalf seconden meten. Hij vindt de flits en de piep over meerdere cycli en biedt aan de gemeten verschuiving op de microfoon toe te passen; de handmatige schuifregelaar blijft er als terugvaloptie. De meting loopt via je scherm en je luidsprekers, dus hun eigen kleine vertragingen tellen mee — en als het mislukt, zegt hij <em>waarom</em>.","manual.825c83c405fb":"Timers, klokken en tekst uit een bestand","manual.85622b429b51":"Een bron <strong>Timer</strong> toont een klok (met je eigen notatie en een optionele vaste UTC-afwijking), <strong>Aftellen</strong> (voor een tijdsduur, of tot het volgende tijdstip van de dag — bij nul kan hij knipperen of van scène wisselen), een <strong>Stopwatch</strong>, of de <strong>tijd sinds je live ging of begon met opnemen</strong>. Start, pauzeer en reset hem vanuit zijn <strong>Eigenschappen</strong>, of koppel de twee globale sneltoetsen die <em>alle</em> timers tegelijk bedienen (<strong>Instellingen → Sneltoetsen</strong>).","manual.fcd4f802968f":"Een bron <strong>Tekst</strong> kan <strong>uit een gevolgd bestand lezen</strong> (<strong>Eigenschappen → Lezen uit bestand</strong>): een heel <code>.txt</code>-bestand, één CSV-cel (op kolomnaam of -nummer), of één JSON-waarde (een pointer zoals <code>/teams/0/score</code>). Wijzigingen verschijnen binnen een halve seconde. Scoreborden en lower thirds zonder dienst erachter.","manual.1d106549f0ce":"De sneltoetsenkaart en de mixerconsole","manual.5d6ad89f147c":"De <strong>Sneltoetsenkaart</strong> (opdrachtenpalet → „Sneltoetsenkaart…”) toont <em>elke</em> koppeling — globale acties en de push-to-talk en push-to-mute van elke bron — doorzoekbaar en filterbaar, en meldt conflicten eerlijk: dezelfde sneltoets die op twee manieren is geschreven, wordt als gedeeld getoond, en bij een toets die het systeem weigerde (omdat een andere app hem bezet) staat dat er ook bij. <strong>Spiekbriefje exporteren</strong> schrijft een naslag in Markdown naar je map Downloads.","manual.e32e382b9753":"Elk mixerkanaal heeft <strong>Pannen</strong> (stereobalans; in het midden is precies geen panning, en dubbelklikken zet het terug), <strong>PFL-solo</strong> (de monitor hoort alleen de kanalen op solo; de programmamix verandert nooit) en een <strong>mono</strong>-downmix. Pannen en mono staan in het menu „⋯” van het kanaal; solo zit op het kanaal zelf.","manual.5dbd70dfc92d":"Apparaten in de diepte: deinterlacing en camerabediening","manual.f8e60899a881":"De <strong>Eigenschappen</strong> van een video-opnameapparaat bieden <strong>Deinterlacing</strong> voor geïnterlinieerde signalen, zoals capture-kaarten die door oudere camera's en consoles worden gevoed: weggooien, bob, lineair, mengen of bewegingsadaptief, met de veldvolgorde. Het werkt op elk systeem hetzelfde; een wijziging herstart het apparaat.","manual.34192e6d30fd":"<strong>Camerabediening</strong> — belichting, witbalans, focus, zoom, versterking en meer — verschijnt in dezelfde <strong>Eigenschappen</strong> zolang de camera draait. Windows en Linux gebruiken de standaard UVC-bediening; macOS toont wat het systeem doorgeeft, en dat is vaak niets, en het paneel zegt dat dan in plaats van schuifregelaars te tonen die niets doen. Elke aanpassing wordt bewaard in een <strong>profiel voor die camera</strong>, dat opnieuw wordt toegepast als je hem weer aansluit of de app herstart; <strong>Profiel resetten</strong> zet de standaardwaarden terug.","manual.f77f10d8c967":"Automatisering en bediening","manual.726216fb4de1":"Laat de studio zichzelf besturen met regels, macro's en hardwarecontrollers — elk daarvan beperkt tot één vaste lijst studio-opdrachten, zodat geen enkele automatisering een bestand kan noemen, een programma kan starten of het internet kan bereiken.","manual.193521bd4921":"Regels, macro's en variabelen","manual.e8ee7ccab125":"Open <strong>Extra → Automatiseringsregels &amp; macro's…</strong> en voeg een regel toe. Kies een van negen triggers (een scènewissel, het starten of stoppen van de stream, het starten of stoppen van de opname, een bronfout, een audioniveau dat een grens overschrijdt, het systeem dat inactief wordt, een venster dat de focus krijgt, een tijdstip van de dag, of een gevolgd bestand dat verandert), voeg voorwaarden toe (de waarde van een variabele, live, opnemen) en kies een studio-actie. Elke regel begint <strong>uitgeschakeld</strong>: zet hem aan om hem te activeren.","manual.5deaa7ba718f":"Bouw een macro als een lijst stappen met een naam — een actie uitvoeren, wachten, een variabele instellen — met een aantal herhalingen en een optionele globale sneltoets. Start hem vanuit de app, met een sneltoets, via een regel of via de API voor bediening op afstand.","manual.30ee5b1326f2":"Stel in een macro een <strong>studiovariabele</strong> in en gebruik die als <code>{{name}}</code> in een willekeurige bron Tekst: de tekst verandert op het moment dat de macro de waarde instelt.","manual.5eb10fc04538":"Controllers: MIDI, OSC en het aanraakpaneel","manual.ba0c838f1688":"Open <strong>Extra → MIDI-bediening…</strong> en leer een pad, draaiknop of fader aan voor een actie, een macro, een scènewissel, een mixerfader of dempen — met lampjes en gemotoriseerde faders die de werkelijke toestand van de studio volgen. Er gaat geen MIDI-poort open totdat je er een kiest.","manual.cc993cb0d974":"Zet <strong>Naar OSC luisteren</strong> aan om controllers in de stijl van TouchOSC en lichttafels adressen te laten sturen zoals <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> en <code>/mixer/vol</code>. Het staat standaard uit en luistert alleen op deze computer, tenzij je je netwerk toestaat. OSC heeft zelf geen wachtwoord.","manual.134e5f4269f9":"Open <strong>Extra → LAN-paneel &amp; tally…</strong> om via een QR-code een bedieningspagina — scèneknoppen met live tally, mixerfaders en actietoetsen — aan elke telefoon aan te bieden. Elk verzoek vereist het wachtwoord, en het luistert alleen op deze computer, tenzij je je netwerk toestaat. De tallypagina toont rood of groen over het hele scherm; voeg <code>?scene=NAME</code> toe om één scène te volgen.","manual.fc4cd96b860d":"Sneltoetsakkoorden en lagen","manual.ec4a9a334753":"Koppel in een sneltoetsveld een gewone sneltoets (Ctrl+Shift+M) of een akkoord in twee stappen (Ctrl+K, dan 3) — de tweede toets wordt alleen geclaimd zolang het akkoord wacht. Geef een koppeling een <strong>Laag</strong>, zodat die alleen werkt zolang die laag actief is; een laag blijft actief totdat je wisselt.","manual.70ad05980925":"Camera's en het draaiboek van de show","manual.24b33b058b99":"Open <strong>Extra → PTZ-camera's…</strong>, voeg een camera toe via zijn VISCA-over-IP-adres, sla presets met een naam op voor pan, tilt en zoom, en koppel een preset aan een scène, zodat het shot wordt opgeroepen als je naar die scène gaat. PTZ blijft op je netwerk, en een camera bestaat alleen omdat jij zijn adres hebt getypt: er wordt naar niets gezocht.","manual.c9d86b995c5a":"Open <strong>Extra → Draaiboek tonen…</strong> en zet de stappen op een rij — een scène, hoe lang die blijft staan en optionele acties — handmatig of automatisch doorschakelend, met een live „hierna” en de resterende tijd. Een draaiboek wisselt scènes op de gewone manier, die je ongedaan kunt maken, en bewerkt je scèneverzameling nooit.","manual.5c94bed2d737":"<strong>Opmerking:</strong> Elke regel, macro, MIDI- of OSC-koppeling, paneelknop en draaiboekstap gaat via dezelfde vaste lijst opdrachten als de API voor bediening op afstand, dus geen enkele controller kan iets wat de eigen knoppen van de app niet kunnen. Elke netwerkluisteraar staat standaard uit en blijft op deze computer tenzij je je netwerk toestaat, en de instellingen voor OSC en het paneel waarschuwen je dat het netwerkverkeer onversleuteld is voordat de poort opengaat.","manual.1f3fd1c7ddc9":"Multistreamen","manual.dcac0a03a29b":"Stream naar meerdere platforms tegelijk — rechtstreeks vanaf je computer, zonder doorstuurdienst ertussen.","manual.42d9628818da":"Voeg in <strong>Instellingen → Stream</strong> twee of meer streambestemmingen toe en zet elk ervan aan.","manual.4144fe0d9694":"Geef een platform eigen encoderinstellingen als het een andere bitrate nodig heeft.","manual.cb21d6bb96be":"Klik op <strong>Ga live</strong>: je zendt tegelijk uit naar elke bestemming die aan staat. Het statistiekendock toont de toestand en bitrate van elke bestemming, en als één bestemming uitvalt, sleept die de andere nooit mee.","manual.aba9a5f55973":"Neem desgewenst tegelijk een lokale kopie met aparte sporen op, en sla replays op met de sneltoets voor replay terwijl je streamt.","manual.af9343c245a7":"<strong>Vandaag gratis:</strong> elke functie — multistream, SRT en WHIP, elk filter, scripts, replay, de overgangspakketten en de API voor bediening op afstand — is vandaag gratis, voor iedereen. Toekomstige versies kunnen worden verkocht.","manual.c08320c45003":"Betrouwbaar streamen en inzicht","manual.532ab322d03c":"Repeteer, meet en verklaar je show. Alles hier staat standaard uit of is neutraal, en niets ervan gaat online.","manual.80390ae1a9d7":"De netwerksimulator","manual.7e620ced841e":"Open in <strong>Instellingen → Stream</strong> de <strong>Netwerksimulator (repetities)</strong> en kies een <strong>Profiel</strong> — <strong>Hotel-wifi</strong>, <strong>Mobiele hotspot</strong>, of <strong>Aangepast</strong> met je eigen <strong>Bandbreedte</strong>, <strong>Latentie</strong>, <strong>Jitter</strong> en geplande momenten van <strong>Uitval</strong>. Het beïnvloedt alleen de lokale uitvoer van een repetitie, dus je kunt herverbinden, multistream en bitratekeuzes oefenen; een echte uitzending kan het nooit vertragen.","manual.b22d8c51e0bd":"Repetitiemodus","manual.083772633b86":"Druk op de paarse knop <strong>Repeteren</strong> om de hele pipeline — compositor, encoder, muxer en de echte logica voor opnieuw verbinden — naar een lokale vervangende bestemming te laten draaien, waarbij <strong>niets de computer verlaat</strong>. Een badge <strong>REPETITIE</strong> markeert elk live-bedieningselement, en je streamsleutels worden niet eens gelezen, dus je kunt repeteren voordat je ze hebt. Je kunt de repetitie ook opnemen.","manual.184d64047c4c":"<strong>Tip:</strong> Combineer een repetitie met de netwerksimulator om ruim vóór de dag zelf te oefenen met opnieuw verbinden over een zwakke, onstabiele verbinding.","manual.d2381a584d24":"De tijdlijn van verloren frames","manual.a6a72c5410a8":"De <strong>Sessietijdlijn</strong> legt de hele sessie vast — rendertijd, encoderwachtrij, de bitrate en verloren frames van elke bestemming, herverbindingen, scènewissels, markeringen en alarmen — in één grafiek waarop je kunt zoomen. Waar het statistiekendock <em>nu</em> toont, beantwoordt de tijdlijn achteraf de vraag „wat gebeurde er in minuut 43?”.","manual.6e9fee1e85fa":"Het sessierapport en de encoder-benchmark","manual.9dd812cbf648":"Zet <strong>Een sessierapport (HTML + Markdown) naast de opname schrijven</strong> aan in <strong>Instellingen → Stream</strong> voor een lokale samenvatting aan het eind van de sessie: uptime, gemiddelde en piekbitrate per bestemming, de tijd dat de stream plat lag, de herverbindingen, markeringen, alarmen en de locatie van de opname. Het blijft op je computer en staat standaard uit.","manual.a9e574b7bd8d":"Gebruik <strong>Encoder-benchmark uitvoeren…</strong> om korte encodes te meten met elke encoder, preset en resolutie die je computer heeft — ongeveer een minuut, volledig offline — en kies daarna in het resultaat <strong>Toepassen op opname-instellingen</strong>. Mislukkingen worden vermeld, niet verborgen, en de benchmark weigert te draaien terwijl je live bent of opneemt.","manual.fae310275ed2":"Bronnen alleen in de stream, of alleen in de opname","manual.191da176dd0d":"Gebruik in de regel van een bron <strong>Tonen in stream</strong> / <strong>Verbergen in stream</strong> en <strong>Tonen in opname</strong> / <strong>Verbergen in opname</strong> om alerts en chat in de livestream te houden terwijl de opname schoon blijft, vanuit één canvas. De hoofdknop met het oog bepaalt nog steeds alles, en het voorbeeld, de projectoren en de multiview tonen altijd het hele programma.","manual.46bad2cb618f":"Virtuele camera","manual.69ebe5277092":"Gebruik je programma als webcam in elke app voor videogesprekken. <strong>Alleen Windows in 1.2.1.</strong>","manual.ba2b6aa952f7":"Klik in <strong>Bediening</strong> op <strong>Virtuele camera starten</strong>. Freally Capture voegt een systeemcamera toe met de naam <strong>„Freally Capture Virtual Camera”</strong>.","manual.cb3cb4585f19":"Kies in Zoom, Meet, Discord of Teams die camera in de video-instellingen: je programma wordt de webcam.","manual.83db59f4a370":"Klik op <strong>Virtuele camera stoppen</strong> om hem te verwijderen.","manual.91c51d55639b":"<strong>Per systeem:</strong> op <strong>Windows</strong> wordt de camera voor jouw gebruiker geregistreerd, zonder beheerdersrechten, en verwijderd als je hem stopt. Hij is <strong>nog niet met code ondertekend</strong>, dus Windows kan ervoor waarschuwen en een strikt beveiligde app voor videogesprekken kan hem weigeren; een volledige test in een echt gesprek moet nog gebeuren. De camera's voor <strong>macOS</strong> en <strong>Linux</strong> zijn aparte componenten die <em>niet in deze versie zitten</em>. Freally Capture installeert nooit een systeemcomponent zonder het te vragen, op geen enkel systeem.","manual.98839b8e6880":"Browserbron","manual.3ba821584b20":"Zet een live webpagina — een overlay voor alerts, een scorebord, een chatwidget — rechtstreeks in een scène.","manual.895f07f428cd":"Klik in <strong>Bronnen</strong> op <strong>+</strong> en kies <strong>Browser</strong>.","manual.868ee19e975e":"Plak een adres met <strong>http://</strong> of <strong>https://</strong> en stel de grootte en framerate in waarmee het wordt weergegeven.","manual.292e94b0a782":"De eerste keer biedt Freally Capture aan om de component <strong>Browserruntime</strong> te installeren. Die wordt gedownload als je erom vraagt en gecontroleerd aan de hand van de hash — nooit meegeleverd met de app — en je kunt hem weer verwijderen via <strong>Extra → Componenten</strong>.","manual.cd6d7fbd46ee":"<strong>Alleen http en https worden geladen.</strong> De regel geldt voor elke paginawissel, niet alleen voor het adres dat je typt: als een pagina naar <code>file://</code>, <code>javascript:</code> of <code>data:</code> probeert te gaan — via een omleiding, een script, een pop-up of een frame — wordt dat <strong>geannuleerd</strong>, zodat een pagina je bestanden niet kan lezen. Op Windows draait de pagina in de sandbox van Chromium. De runtime is <strong>nog niet met code ondertekend</strong>. Het geluid van de pagina wordt nog niet opgenomen: deze versie levert alleen beeld.","manual.9c0c8f127dd9":"Game-opname","manual.2c08692420b8":"Neem een game in exclusief volledig scherm op die gewone vensteropname niet kan zien. <strong>Alleen Windows.</strong>","manual.9d162e3861e9":"Klik in <strong>Bronnen</strong> op <strong>+</strong> en kies <strong>Spelopname</strong>. <strong>Lees eerst de mededeling</strong>: die legt het risico in gewone woorden uit.","manual.4264b41a7732":"Accepteer het risico <em>voor die ene game</em> en kies daarna de draaiende game uit de lijst.","manual.ab3e826e90f1":"Freally Capture laadt een kleine hook in die game en neemt de frames op met de eigen framerate van de game.","manual.082fd06e18f9":"<strong>Lees dit voordat je het gebruikt.</strong> Game-opname werkt door <strong>een DLL in de game te laden</strong>. Anti-cheat- en antivirussoftware kan dat als manipulatie zien, en het kan een account een <strong>ban</strong> opleveren. Er wordt nooit iets automatisch geladen: je geeft toestemming <strong>voor één game tegelijk</strong>, en die toestemming kan nooit voor een andere game worden gebruikt — en gaat nooit mee in een gedeelde scèneverzameling. Als een game de hook weigert, valt Freally Capture met een melding terug op gewone <strong>Vensteropname</strong> in plaats van te mislukken. HDR-games en Direct3D 12-games gebruiken ook Vensteropname. Op macOS en Linux wordt deze bron niet aangeboden.","manual.43fae75af922":"Replaybuffer","manual.40bc664c1c0b":"Houd de laatste momenten in het geheugen, zodat een sneltoets bewaart wat er net gebeurde.","manual.7a69241c10c2":"Klik in <strong>Bediening</strong> op <strong>Replaybuffer starten</strong>. Freally Capture houdt de laatste seconden bij in een buffer met een vaste grootte.","manual.684aecea2ba0":"Koppel in <strong>Instellingen</strong> een globale sneltoets voor <strong>Replay opslaan</strong>.","manual.66c44777e965":"Druk erop om de laatste seconden in een bestand op te slaan — zonder je stream of je hoofdopname te onderbreken. Een melding „Replay opgeslagen” bevestigt het.","manual.4b598d5daf11":"Autocue","manual.b7fc474ded62":"Een vloeiend scrollend script voor wie voor de camera staat — op een paneel in de app, op een projector op volledig scherm die gespiegeld kan worden en op het aanraakpaneel op het lokale netwerk, allemaal tegelijk.","manual.f1c548f77750":"Open de autocue via <strong>Extra</strong>, typ of plak je script en stel de snelheid en het lettertype in. Stel het tempo in op <strong>tekens per seconde</strong>, of schakel over naar <strong>BPM</strong> (50–250 tellen per minuut) om songteksten in de maat van de muziek te lezen; beide wijzigingen passen het tempo van een lopende scroll meteen aan.","manual.3a86eb91938d":"<strong>Pauzechips:</strong> typ <code> -- </code> voor een korte tel of <code> --N </code> voor een pauze van N seconden, en het wordt één chip — de cursor stapt eroverheen, één keer Delete of Backspace verwijdert hem, en kopiëren en plakken houden hem heel.","manual.dc7539148aed":"<strong>Aftellen starten:</strong> activeer een optionele aanloop van 3-2-1, getoond op zowel het voorbeeld van de operator als de projector, zodat de lezer even tijd heeft voordat de tekst beweegt.","manual.f5113c573ac4":"<strong>Open de projector</strong> voor de lezer (de spiegelmodus draait het beeld om voor glas met een beamsplitter). Als je hem opent, sluit het operatorvenster, zodat je de stream vanuit het hoofdvenster kunt draaien terwijl de lezer leest; met een geactiveerde aftelling gaat de projector terug naar het begin, telt af en speelt af. Afspelen, pauzeren, stoppen, terugspoelen, vooruitspoelen en opnieuw beginnen gaat met de bediening op het scherm, een sneltoets, MIDI, OSC of het LAN-paneel — alle bediening blijft synchroon.","manual.5298a60b0152":"<strong>Voorlezen</strong> laat het script horen met de eigen spraak van je systeem: de ingebouwde stemmen van Windows, die van macOS, en op Linux <code>spd-say</code> of <code>espeak-ng</code> als die zijn geïnstalleerd. Er wordt geen spraakengine meegeleverd.","manual.5de1b5efa245":"<strong>Automatisch aanvullen</strong> stelt tijdens het typen woorden en zinsdelen voor in lichtgrijs; druk op Tab om te accepteren. Elk van de 18 talen heeft een eigen woordenboek op je computer, dat alleen wordt geladen voor de taal waarin je schrijft.","manual.7fb5d22a1670":"Bediening op afstand","manual.b2ba73efdcec":"Bestuur de studio vanaf een Stream Deck of een controller in de stijl van Companion — standaard uit, met een wachtwoord beveiligd, op je eigen computer.","manual.6396674fcd28":"Open <strong>Instellingen → Bediening op afstand</strong>, zet de <strong>WebSocket-API</strong> aan (standaard uit) en stel een <strong>wachtwoord</strong> in.","manual.56e0d6d295bb":"Hij luistert op <code>127.0.0.1</code> — alleen deze computer — tenzij je je netwerk uitdrukkelijk toestaat.","manual.344e52e3eba1":"Richt een Companion- of Stream Deck-client op het getoonde adres. Wissel van scène, voer overgangen uit, demp en hef het dempen op, start en stop opnames en sla replays op met hardwareknoppen.","manual.6664edd9ad4c":"Gasten op afstand en uitzendproductie","manual.75ce17238f9b":"Maak van een sessie met gasten op afstand een geproduceerde show: tot acht gasten, tekenen op het live programma, een wachtruimte, privé-cues, de verbinding van elke gast in één oogopslag en een automatisch raster. Alles hier staat standaard uit of is niet gekoppeld, en er wordt niets verbonden totdat je iemand uitnodigt.","manual.02d9e34002c8":"Sessies met meerdere gasten","manual.5a6c2ec7640d":"Start een sessie met gasten op afstand en deel de uitnodigingslink of de QR-code ervan: <strong>jij plus tot acht gasten</strong>, een galerij van één tot negen. Elke gast is een tegel met eigen dempknoppen, verbindingskwaliteit, cuekanaal en één klik om in de uitzending te zetten.","manual.34a323a45540":"Een gast opent de link in een webbrowser — niets te installeren — en tikt op <strong>Meedoen</strong> om camera en microfoon te sturen. Een gast die Freally Capture heeft, kan dezelfde uitnodiging in plaats daarvan in de app openen. Een uitnodiging verloopt na de tijd die jij kiest.","manual.4e31042e4a6f":"<strong>Opmerking:</strong> Beeld en geluid gaan rechtstreeks tussen jou en elke gast, peer-to-peer en versleuteld onderweg; alleen het opzetten van de verbinding loopt via een openbare signaleringsdienst. Sessies zijn getest met vier gasten; meer hangt af van je bandbreedte en processor.","manual.33ff43cd0616":"Telestrator: tekenen op het live programma","manual.d29f651d6eb9":"Open de <strong>Telestrator</strong> en kies een gereedschap — <strong>Pen</strong>, <strong>Markeerstift</strong>, <strong>Pijl</strong> of <strong>Ellips</strong> — en teken rechtstreeks op het programma. Je markeringen maken deel uit van het beeld zodra je ze tekent, dus ze verschijnen in de opname en de stream, niet alleen in je voorbeeld.","manual.9aa7fc0273fb":"Laat markeringen na een tijdje <strong>Vervagen</strong>, of schakel over naar <strong>Whiteboardmodus</strong> om ze te <strong>Behouden</strong> totdat je ze wist. Tekenen volgt de druk van een tekentablet, en <strong>Markeringen wissen</strong> kan aan een sneltoets worden gekoppeld (standaard niet gekoppeld).","manual.fc81cd8d37ae":"De wachtruimte","manual.c87beb96ec64":"Zet de <strong>Wachtruimte</strong> aan en nieuwe gasten wachten buiten de uitzending terwijl jij hun camera en microfoon controleert in het <strong>Wachtruimte-voorbeeld</strong>. Als ze klaar zijn, klik je op <strong>In de uitzending zetten</strong>. De gast ziet een banner „je zit in de wachtruimte”, in de app of op de webpagina.","manual.1d47c8224f50":"Cues geven en praten","manual.569d461035c1":"Stuur een gast een privé-<strong>Cue</strong> — met presets zoals <strong>30 seconden</strong>, <strong>Rond af</strong>, <strong>Jij bent zo aan de beurt</strong> en <strong>Spreek luider</strong> — via het bestaande peer-to-peerkanaal van de sessie. De gast ziet hem met een live aftelling, nooit in het programma.","manual.c66c9d5359bf":"Het dashboard voor verbindingskwaliteit","manual.4541cc1ee0f5":"Volg de verbinding van elke gast live — round-trip-tijd, pakketverlies, de resolutie en framerate die je ontvangt, en jitter — met een groene, amberkleurige of rode badge en een kleine grafiek met de geschiedenis, zodat een zwakker wordende verbinding zichtbaar is voordat je kijkers het merken.","manual.bf8e764221e5":"Automatische gastenrasters","manual.ffe3c227cdfc":"Zet <strong>Auto-raster</strong> aan om gasten in de uitzending in een net raster van één tot negen te houden dat zichzelf herschikt als gasten meedoen, vertrekken of in de uitzending worden gezet, of druk op de knop voor schikken om het meteen te doen. Elke plek publiceert de naam van de gast als variabele <code>{{guestN}}</code>, zodat een titelbron een naamplaatje wordt dat zichzelf bijwerkt.","manual.e8630fabd4e5":"Studiobeheer en werkwijze","manual.c8c487196725":"Maak een hele indeling draagbaar en deelbaar, bewaar versies van je scènes met een naam, geef de app een thema en zet je favoriete acties op één tik afstand — allemaal op je computer, zonder server.","manual.f87995a7cf6c":"Scènepakketten en versies","manual.074bb2bf9453":"Open het werkruimtevenster via <strong>Scèneverzameling → Scèneverzamelingen beheren…</strong>: de gereedschappen voor pakketten, vergelijken, momentopnamen, back-ups en dockindelingen staan daar allemaal.","manual.8dce3a052a05":"Klik op <strong>Pakket exporteren…</strong> om de huidige verzameling en haar bestanden (afbeeldingen, media, LUT's, maskers, lettertypen) te bundelen in één draagbaar <code>.fcappack</code>. Webadressen en netwerkpaden worden als <em>extern</em> vermeld in plaats van meegebundeld, en lettertypen worden gemarkeerd vanwege hun licenties.","manual.c1bba88df9c5":"Klik op <strong>Pakket importeren…</strong> en kies een <code>.fcappack</code>: het komt binnen als nieuwe verzameling, vindt zijn bestanden op deze computer en schakelt ernaar over.","manual.69e7b9f6e8ab":"Klik op <strong>Vergelijken &amp; samenvoegen…</strong> om de huidige verzameling te vergelijken met een andere verzameling, een pakket of een momentopname. Bekijk de toegevoegde, verwijderde en gewijzigde scènes, bronnen, transformaties, filters en zichtbaarheid, en kies daarna precies welke wijzigingen je overneemt. Kies je een scène, dan komen de bronnen die ze gebruikt mee.","manual.862a75c84629":"Klik op <strong>Momentopnamen…</strong>, geef een controlepunt een naam en kies <strong>Momentopname opslaan</strong>. <strong>Herstellen</strong> haalt het later terug — je huidige indeling wordt eerst als momentopname bewaard, dus herstellen is nooit onomkeerbaar. Er worden tot 50 momentopnamen bewaard, met hun schijfgebruik erbij.","manual.8058b1480d14":"<strong>Tip:</strong> Momentopnamen zijn geschiedenis met een naam, naast automatisch opslaan en ongedaan maken. Maak er een vóór een riskante wijziging, en je hebt altijd een gemarkeerd punt om naar terug te gaan.","manual.1d55a62a5fdf":"Back-up, herstel en draagbare modus","manual.250b89a976de":"Klik in het werkruimtevenster op <strong>Back-up en herstel…</strong> en daarna op <strong>Back-up exporteren…</strong> om alles — instellingen, profielen en scèneverzamelingen — in één <code>.fcapbackup</code>-bestand op te slaan.","manual.560e7e269f11":"Klik op een nieuwe computer op <strong>Herstellen vanuit back-up…</strong>, vink aan wat je wilt overnemen (<strong>Instellingen</strong>, <strong>Scèneverzamelingen</strong>, <strong>Profielen</strong>) en kies <strong>Geselecteerde herstellen</strong>. Start Freally Capture daarna opnieuw om de herstelde verzamelingen en profielen te laden.","manual.5b26da4b8793":"Om vanaf een USB-stick te werken, zet je een bestand met de naam <code>freally-portable.txt</code> naast het programma: al zijn gegevens staan dan in de map van het programma in plaats van in je gebruikersprofiel. <strong>Instellingen → Over</strong> toont of de draagbare modus aan staat en waar de gegevens staan.","manual.a31a49d41d7d":"<strong>Opmerking:</strong> Streamsleutels en wachtwoorden worden nooit in een back-up geschreven — voer ze na het herstellen opnieuw in.","manual.5b446c4ea972":"Thema's, indelingen en snelacties","manual.8eea476bde73":"Open <strong>Instellingen → Weergave</strong> en kies het thema <strong>Aangepast</strong> om het palet te bewerken, met live <strong>contrastwaarschuwingen</strong>, en gebruik daarna <strong>.fctheme exporteren…</strong> of <strong>.fctheme importeren…</strong> om het te delen.","manual.7cc0bc3a4e74":"Sla in de <strong>Dockindelingen</strong> van het werkruimtevenster de huidige schikking op onder een naam, en klik op een opgeslagen indeling om ernaar over te schakelen.","manual.c9044c09b979":"Typ in <strong>Instellingen</strong> in <strong>Instellingen zoeken…</strong> om naar elke instelling te springen; een markering laat zien in welke categorieën je iets hebt gewijzigd sinds je het venster opende.","manual.a4640858ad4d":"Kies <strong>Extra → Snelacties…</strong> om het knoppenraster te openen. Klik op <strong>Bewerken</strong> en daarna op <strong>Knop toevoegen</strong>, stel voor elke knop het label en de kleur in, en voeg <strong>pagina's</strong> toe. Een knop kan van scène wisselen, een macro uitvoeren, een soundboardpad afspelen of een studio-opdracht uitvoeren.","manual.74ff6472576d":"<strong>Tip:</strong> Knoppen voor snelacties voeren dezelfde studio-opdrachten uit als sneltoetsen, en het raster wordt gedeeld met het aanraakpaneel op het lokale netwerk: stel het één keer in en het staat ook op je telefoon.","manual.74a883a037bc":"Instellingen","manual.5feaf4600834":"Profielen, scèneverzamelingen, sneltoetsen en taal. Alles is vandaag gratis, dus er hoeft niets te worden geactiveerd. <strong>Instellingen</strong> is één venster met categorieën — Algemeen, Weergave, Streamen, Uitvoer, Replay, Sneltoetsen, Netwerk, Toegankelijkheid en Over — dat je opent via de <strong>menubalk</strong> (Bestand, Bewerken, Beeld, Docks, Profiel, Scèneverzameling, Extra en Help).","manual.9f6a04e85e39":"<strong>Toepassen betekent toepassen.</strong> Het venster Instellingen bewerkt een kopie: er verandert niets totdat je op <strong>Toepassen</strong> of <strong>OK</strong> klikt, en <strong>Annuleren</strong> zet precies terug wat je had, het voorbeeld van het thema inbegrepen.","manual.3fc0968ef6f9":"<strong>Profielen en scèneverzamelingen:</strong> houd aparte opstellingen — bijvoorbeeld „Streamen” en „Lokaal opnemen” — en wissel ertussen zonder opnieuw te starten, via de menu's <strong>Profiel</strong> en <strong>Scèneverzameling</strong>.","manual.ce6f52861bdb":"<strong>Sneltoetsen:</strong> koppel elke actie vanuit een lijst die geen conflicten kan opleveren — kies een sneltoets voor één actie en hij verdwijnt uit de lijst van elke andere actie, zodat twee functies nooit een toets delen. <strong>Geen</strong> maakt hem weer vrij.","manual.be52349f05be":"<strong>Toegankelijkheid:</strong> kies de meterkleuren van de mixer, waaronder een set die geschikt is voor kleurenblinden. De hele app werkt met het toetsenbord, en schermlezers kondigen live gaan, opnemen, opnieuw verbinden en verloren frames aan.","manual.a79c94673558":"<strong>Taal:</strong> kies een van 18 talen; de app verandert meteen, en Arabisch leest van rechts naar links.","manual.59274c49ac87":"Een probleem melden","manual.c02ed8aec89d":"Jij beslist of een probleem de ontwikkelaar bereikt, en je ziet precies wat er verstuurd zou worden.","manual.4ed327c34aeb":"Als de app een fout toont die hij zelf heeft veroorzaakt, verschijnt er een knop <strong>Melden</strong> naast.","manual.95da4b53fdcc":"Na een crash biedt de volgende start <strong>Melden</strong> of <strong>Sluiten</strong> aan.","manual.6207904599f4":"<strong>Melden</strong> opent de meldingspagina van Freally Capture op deze website in je browser, met de technische gegevens al ingevuld: je kunt ze lezen, maar niet wijzigen. Voeg toe wat je aan het doen was en, als je wilt, een e-mailadres. Er wordt niets verstuurd tenzij je daar op <strong>Verzenden</strong> drukt.","manual.6acd4e789ccd":"Er wordt nooit iets op de achtergrond verstuurd, en <strong>Sluiten</strong> verstuurt helemaal niets.","manual.69bd78234ffb":"Privacy en het netwerk","manual.42f9b04c2640":"Freally Capture heeft geen account en geen telemetrie, en er is geen clouddienst van ons. Hier staat precies wat er online gaat, en wat niet.","manual.81fe73d241a8":"<strong>Geen account, geen telemetrie.</strong> De app vraagt je nooit om in te loggen en stuurt je scènes, opnames of gebruiksgegevens nooit ergens heen.","manual.3735a28566e9":"<strong>Je stream gaat rechtstreeks naar het platform.</strong> Hij gaat van je computer naar de diensten die je instelt — er zit geen doorstuurserver van ons tussen.","manual.512b8fa00684":"<strong>Je opnames blijven op je computer,</strong> in de map die je kiest. Er wordt niets geüpload.","manual.c299fcfa1fde":"<strong>Je streamsleutels blijven op je computer,</strong> worden gemaskeerd getoond en alleen verstuurd naar de dienst waarnaar je streamt.","manual.414a08bd0219":"<strong>Gasten op afstand verbinden peer-to-peer.</strong> Alleen het opzetten van de verbinding voor de sessie loopt via een openbare signaleringsdienst, en alleen als je een sessie start.","manual.20c95c4687b3":"<strong>Een chat-overlay leest de openbare chat</strong> van het kanaal waarop je hem richt, zoals een niet-ingelogde kijker dat zou doen — zonder account, sleutel of inloggen.","manual.efe87d55bed1":"<strong>Twee componenten worden pas gedownload als je ze voor het eerst nodig hebt:</strong> ffmpeg, voor de codecs die de platforms eisen, en de browserruntime, voor de browserbron. Elk komt van zijn eigen uitgever en wordt vóór gebruik gecontroleerd.","manual.3601a272b3b0":"<strong>Een updatecontrole</strong> haalt één klein bestand op bij elke start, en wanneer je <strong>Controleren op updates…</strong> kiest. Er wordt niets over jou of je computer meegestuurd, en er wordt niets geïnstalleerd tenzij je ja zegt.","manual.11abc96d8e21":"<strong>Een probleemmelding wordt alleen verstuurd als je op Verzenden drukt</strong> op de meldingspagina, nadat je hebt gelezen wat erin staat (zie <a href=\"#report\">Een probleem melden</a>).","manual.804fa6536d40":"<strong>Geen AI.</strong> Elk filter — ruisonderdrukking, chroma key, tonemapping — is klassieke signaalverwerking. De app bevat geen machine-learningmodel en downloadt er ook geen."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
